css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: 180mm 100mm;
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.print-format {
  page-width: 180mm;
  page-height: 100mm;
  margin-top: 0mm !important;
  margin-right: 0mm !important;
  margin-bottom: 0mm !important;
  margin-left: 0mm !important;
  width: 179mm !important;
  height: 99mm !important;
  min-height: 99mm !important;
  max-height: 99mm !important;
  padding: 0 !important;
  overflow: hidden !important;
}

.print-format-gutter {
  box-sizing: border-box;
  width: 179mm !important;
  height: 99mm !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
}

.cd-shipment-box-label,
.cd-shipment-box-label * {
  box-sizing: border-box;
}

.cd-shipment-box-label {
  position: relative;
  width: 179mm;
  height: 99mm;
  overflow: hidden;
  padding: 5mm;
  color: #111;
  background: #fff;
  font-family: "TH Sarabun Document", sans-serif;
  font-size: 4.2mm;
  line-height: 1.08;
}

.cd-shipment-box-label .label-header {
  position: relative;
  height: 20mm;
  border-bottom: 0.6mm solid #111;
}

.cd-shipment-box-label .company-logo {
  display: block;
  width: 48mm;
  height: 15mm;
  object-fit: contain;
  object-position: left center;
}

.cd-shipment-box-label .territory {
  position: absolute;
  top: 0;
  right: 0;
  max-width: 76mm;
  min-height: 12mm;
  padding: 2.2mm 4mm;
  overflow: hidden;
  color: #fff;
  background: #111;
  font-size: 5.6mm;
  font-weight: 700;
  line-height: 1;
  text-align: center;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.cd-shipment-box-label .party-section {
  position: relative;
  display: block;
  width: 100%;
  height: 69mm;
  overflow: hidden;
  border-bottom: 0.35mm solid #111;
}

.cd-shipment-box-label .party-panel {
  position: absolute;
  top: 0;
  width: 50%;
  height: 69mm;
  min-width: 0;
  padding: 3mm 4mm 2mm;
  overflow: hidden;
}

.cd-shipment-box-label .sender-panel { left: 0; }
.cd-shipment-box-label .recipient-panel { left: 50%; }

.cd-shipment-box-label .party-panel + .party-panel {
  border-left: 0.35mm solid #111;
}

.cd-shipment-box-label h1 {
  margin: 0 0 1.5mm;
  font-size: 5.4mm;
  font-weight: 700;
  line-height: 1;
}

.cd-shipment-box-label h1 span {
  font-size: 3.5mm;
  font-weight: 400;
}

.cd-shipment-box-label .party-name,
.cd-shipment-box-label .party-address,
.cd-shipment-box-label .party-phone {
  max-width: 100%;
  overflow: hidden;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.cd-shipment-box-label .party-name {
  max-height: 12mm;
  margin-bottom: 1.5mm;
  font-size: 4.8mm;
  font-weight: 700;
}

.cd-shipment-box-label .party-address {
  height: 34mm;
  font-size: 4mm;
  white-space: pre-line;
}

.cd-shipment-box-label .party-address p {
  margin: 0;
}

.cd-shipment-box-label .party-phone {
  height: 8mm;
  padding-top: 1mm;
  font-size: 4mm;
  white-space: normal;
}

.cd-shipment-box-label .label-footer { display: none; }

html:
{# Shipment Box Label — single-page 180 x 100 mm label. #}

{% set sender_type = doc.pickup_from_type or "" %}
{% set recipient_type = doc.delivery_to_type or "" %}
{% if sender_type == "Company" %}
  {% set sender_id = doc.pickup_company %}
  {% set sender_name = frappe.db.get_value("Company", sender_id, "company_name") or sender_id %}
{% elif sender_type == "Customer" %}
  {% set sender_id = doc.pickup_customer %}
  {% set sender_name = frappe.db.get_value("Customer", sender_id, "customer_name") or sender_id %}
{% elif sender_type == "Supplier" %}
  {% set sender_id = doc.pickup_supplier %}
  {% set sender_name = frappe.db.get_value("Supplier", sender_id, "supplier_name") or sender_id %}
{% else %}
  {% set sender_id = "" %}
  {% set sender_name = doc.pickup or "" %}
{% endif %}
{% if recipient_type == "Company" %}
  {% set recipient_id = doc.delivery_company %}
  {% set recipient_name = frappe.db.get_value("Company", recipient_id, "company_name") or recipient_id %}
{% elif recipient_type == "Customer" %}
  {% set recipient_id = doc.delivery_customer %}
  {% set recipient_name = frappe.db.get_value("Customer", recipient_id, "customer_name") or recipient_id %}
{% elif recipient_type == "Supplier" %}
  {% set recipient_id = doc.delivery_supplier %}
  {% set recipient_name = frappe.db.get_value("Supplier", recipient_id, "supplier_name") or recipient_id %}
{% else %}
  {% set recipient_id = "" %}
  {% set recipient_name = doc.delivery_to or "" %}
{% endif %}
{% set sender_address = (doc.pickup_address or "") | replace("<br />", "~#~") | replace("<br/>", "~#~") | replace("<br>", "~#~") | replace("</p>", "~#~") | replace("</div>", "~#~") | replace("</li>", "~#~") | striptags | replace("~#~", "\n") | trim %}
{% set sender_contact_text = (doc.pickup_contact or "") | replace("<br />", "~#~") | replace("<br/>", "~#~") | replace("<br>", "~#~") | striptags | trim %}
{% set sender_contact_lines = sender_contact_text.split("~#~") %}
{% set sender_contact_last = sender_contact_lines[-1] | trim if sender_contact_lines else "" %}
{% set sender_contact_digits = sender_contact_last | select("in", "0123456789") | list | length %}
{% set sender_snapshot_phone = sender_contact_last if sender_contact_last and "@" not in sender_contact_last and sender_contact_digits >= 6 else "" %}
{% set sender_mobile = frappe.db.get_value("Contact", doc.pickup_contact_name, "mobile_no") if doc.pickup_contact_name else "" %}
{% set sender_contact_phone = frappe.db.get_value("Contact", doc.pickup_contact_name, "phone") if doc.pickup_contact_name else "" %}
{% set sender_address_phone = frappe.db.get_value("Address", doc.pickup_address_name, "phone") if doc.pickup_address_name else "" %}
{% set sender_phone = sender_snapshot_phone or sender_mobile or sender_contact_phone or sender_address_phone %}
{% set recipient_address = (doc.delivery_address or "") | replace("<br />", "~#~") | replace("<br/>", "~#~") | replace("<br>", "~#~") | replace("</p>", "~#~") | replace("</div>", "~#~") | replace("</li>", "~#~") | striptags | replace("~#~", "\n") | trim %}
{% set recipient_contact_text = (doc.delivery_contact or "") | replace("<br />", "~#~") | replace("<br/>", "~#~") | replace("<br>", "~#~") | striptags | trim %}
{% set recipient_contact_lines = recipient_contact_text.split("~#~") %}
{% set recipient_contact_last = recipient_contact_lines[-1] | trim if recipient_contact_lines else "" %}
{% set recipient_contact_digits = recipient_contact_last | select("in", "0123456789") | list | length %}
{% set recipient_snapshot_phone = recipient_contact_last if recipient_contact_last and "@" not in recipient_contact_last and recipient_contact_digits >= 6 else "" %}
{% set recipient_mobile = frappe.db.get_value("Contact", doc.delivery_contact_name, "mobile_no") if doc.delivery_contact_name else "" %}
{% set recipient_contact_phone = frappe.db.get_value("Contact", doc.delivery_contact_name, "phone") if doc.delivery_contact_name else "" %}
{% set recipient_address_phone = frappe.db.get_value("Address", doc.delivery_address_name, "phone") if doc.delivery_address_name else "" %}
{% set recipient_phone = recipient_snapshot_phone or recipient_mobile or recipient_contact_phone or recipient_address_phone %}
{% set recipient_territory = frappe.db.get_value("Customer", recipient_id, "territory") if recipient_type == "Customer" and recipient_id else "" %}

{# This label is intentionally one physical page and needs no pagination loop. #}

<article class="cd-shipment-box-label">
  <header class="label-header">
    <img class="company-logo" src="/assets/connect_diagnostics_core/images/cd_logo_v2.jpg" alt="Connect Diagnostics">
    {% if recipient_territory %}<div class="territory">{{ recipient_territory | truncate(40, True, "…") }}</div>{% endif %}
    <footer class="label-footer"></footer>
  </header>

  <section class="party-section">
    <section class="party-panel sender-panel">
      <h1>ผู้ส่ง <span>Sender</span></h1>
      <div class="party-name">{{ (sender_name or "") | truncate(80, True, "…") }}</div>
      <div class="party-address">{{ sender_address | truncate(150, True, "…") }}</div>
      {% if sender_phone %}<div class="party-phone">โทร/Tel. {{ sender_phone }}</div>{% endif %}
    </section>
    <section class="party-panel recipient-panel">
      <h1>ผู้รับ <span>Recipient</span></h1>
      <div class="party-name">{{ (recipient_name or "") | truncate(80, True, "…") }}</div>
      <div class="party-address">{{ recipient_address | truncate(150, True, "…") }}</div>
      {% if recipient_phone %}<div class="party-phone">โทร/Tel. {{ recipient_phone }}</div>{% endif %}
    </section>
  </section>

</article>
